/**
 * 縮圖預覽插件
 *
 * 在進度條懸停時顯示對應時間點的視頻縮圖
 * 使用 WebGL 渲染 YUV420 格式的縮圖數據
 */

import type { MpvPlugin, PluginInstance } from '../../core/types/plugin';
import type { MpvVideoElement } from '../../renderer/ui/MpvVideoElement';
import { WebGLVideoRenderer } from '../../renderer/video-player/webgl-renderer';
import styles from './styles.css?inline';

/**
 * 縮圖插件配置
 */
export interface ThumbnailPluginOptions {
    /** 縮圖寬度，默認 160 */
    width?: number;
    /** 縮圖高度，默認 90 */
    height?: number;
}

/**
 * 縮圖數據（從 thumbnail 事件接收）
 */
interface ThumbnailData {
    buffer: ArrayBuffer;
    width: number;
    height: number;
    format: 'rgba' | 'yuv420';
    rotation?: number;
    time: number;
}

/**
 * 縮圖插件定義
 */
export const ThumbnailPlugin: MpvPlugin<ThumbnailPluginOptions> = {
    name: 'thumbnail',
    version: '1.0.0',
    dependencies: ['controlBar'],
    styles,

    install(player, options = {}) {
        return new ThumbnailManager(player, {
            width: options.width ?? 160,
            height: options.height ?? 90,
        });
    },
};

/**
 * 縮圖管理器
 */
export class ThumbnailManager implements PluginInstance {
    readonly name = 'thumbnail';

    private player: MpvVideoElement;
    private options: Required<ThumbnailPluginOptions>;

    // DOM 元素
    private tooltipEl: HTMLElement | null = null;
    private thumbnailCanvas: HTMLCanvasElement | null = null;
    private thumbnailWrapper: HTMLElement | null = null;

    // WebGL 渲染器（處理 YUV420 轉換）
    private renderer: WebGLVideoRenderer | null = null;

    // 狀態
    private _enabled: boolean = true;
    private isHovering: boolean = false;

    // 事件取消訂閱
    private eventUnsubscribe: (() => void) | null = null;

    // 事件處理器引用（用於清理）
    private boundOnProgressHover: ((e: MouseEvent) => void) | null = null;
    private boundOnProgressLeave: (() => void) | null = null;
    /** 緩存進度條容器元素，避免 destroy 時重複查詢 */
    private progressContainer: Element | null = null;

    constructor(player: MpvVideoElement, options: Required<ThumbnailPluginOptions>) {
        this.player = player;
        this.options = options;

        this.initialize();
    }

    private initialize(): void {
        const shadowRoot = this.player.shadowRoot;
        if (!shadowRoot) return;

        // 找到進度條 tooltip
        this.tooltipEl = shadowRoot.querySelector('.mpv-progress-tooltip, .vp-progress-tooltip');
        if (!this.tooltipEl) return;

        // 創建縮圖容器
        this.thumbnailWrapper = document.createElement('div');
        this.thumbnailWrapper.className = 'mpv-tooltip-thumbnail-wrapper';
        this.thumbnailWrapper.style.cssText = `
            width: ${this.options.width}px;
            height: ${this.options.height}px;
            display: none;
            margin-bottom: 4px;
        `;

        // 創建縮圖 canvas（用於 WebGL 渲染）
        this.thumbnailCanvas = document.createElement('canvas');
        this.thumbnailCanvas.className = 'mpv-tooltip-thumbnail';
        this.thumbnailCanvas.width = this.options.width;
        this.thumbnailCanvas.height = this.options.height;
        this.thumbnailCanvas.style.cssText = `
            width: 100%;
            height: 100%;
            border-radius: 4px;
        `;

        this.thumbnailWrapper.appendChild(this.thumbnailCanvas);
        this.tooltipEl.insertBefore(this.thumbnailWrapper, this.tooltipEl.firstChild);

        // 創建 WebGL 渲染器
        try {
            this.renderer = new WebGLVideoRenderer(this.thumbnailCanvas);
        } catch {
            console.warn('[ThumbnailPlugin] WebGL not available, thumbnails disabled');
            return;
        }

        // 綁定進度條懸停事件
        this.bindEvents();

        // 訂閱縮圖事件
        this.subscribeToThumbnailEvents();
    }

    private bindEvents(): void {
        const shadowRoot = this.player.shadowRoot;
        if (!shadowRoot) return;

        // 緩存 progressContainer，在 destroy 時複用
        this.progressContainer = shadowRoot.querySelector('.mpv-progress-container, .vp-progress-container');
        if (!this.progressContainer) return;

        this.boundOnProgressHover = this.onProgressHover.bind(this);
        this.boundOnProgressLeave = this.onProgressLeave.bind(this);

        this.progressContainer.addEventListener('mousemove', this.boundOnProgressHover as EventListener);
        this.progressContainer.addEventListener('mouseleave', this.boundOnProgressLeave as EventListener);
    }

    private subscribeToThumbnailEvents(): void {
        // 監聯 thumbnail DOM 事件
        const handleThumbnail = (e: Event) => {
            const event = e as CustomEvent<ThumbnailData>;
            this.onThumbnailReceived(event.detail);
        };

        this.player.addEventListener('thumbnail', handleThumbnail);
        this.eventUnsubscribe = () => {
            this.player.removeEventListener('thumbnail', handleThumbnail);
        };
    }

    private onProgressHover(e: MouseEvent): void {
        if (!this._enabled || !this.renderer) return;

        const progressBar = (e.currentTarget as HTMLElement).querySelector('.mpv-progress-bar, .vp-progress-bar');
        if (!progressBar) return;

        const rect = progressBar.getBoundingClientRect();
        const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
        const time = percent * this.player.duration;

        this.isHovering = true;
        this.requestThumbnail(time);
    }

    private onProgressLeave(): void {
        this.isHovering = false;
        this.clearThumbnail();
    }

    private requestThumbnail(time: number): void {
        this.fetchThumbnail(time);
    }

    private fetchThumbnail(time: number): void {
        // 調用 player 的 requestScreenshot 方法
        const playerWithScreenshot = this.player as unknown as { requestScreenshot?: (time: number) => Promise<boolean> };
        if (typeof playerWithScreenshot.requestScreenshot === 'function') {
            playerWithScreenshot.requestScreenshot(time).catch((error) => {
                console.error('[ThumbnailPlugin] Failed to request screenshot:', error);
            });
        }
    }

    private onThumbnailReceived(data: ThumbnailData): void {
        if (!this.isHovering || !this.renderer || !this.thumbnailWrapper) return;

        const { buffer, width, height, format, rotation } = data;

        if (!buffer || width <= 0 || height <= 0) return;

        try {
            // 使用 WebGL 渲染器處理 YUV420/RGBA 數據
            this.renderer.updateFrameFromBuffer(buffer, width, height, rotation ?? 0, format);

            // 顯示縮圖
            this.thumbnailWrapper.style.display = 'block';
        } catch (error) {
            console.error('[ThumbnailPlugin] Failed to render thumbnail:', error);
        }
    }

    private clearThumbnail(): void {
        if (this.thumbnailWrapper) {
            this.thumbnailWrapper.style.display = 'none';
        }
    }

    // ===== 公開 API =====

    enable(): void {
        this._enabled = true;
    }

    disable(): void {
        this._enabled = false;
        this.clearThumbnail();
    }

    get enabled(): boolean {
        return this._enabled;
    }

    destroy(): void {
        // 取消事件訂閱
        if (this.eventUnsubscribe) {
            this.eventUnsubscribe();
        }

        // 移除事件監聽（使用緩存的 progressContainer）
        if (this.progressContainer && this.boundOnProgressHover && this.boundOnProgressLeave) {
            this.progressContainer.removeEventListener('mousemove', this.boundOnProgressHover as EventListener);
            this.progressContainer.removeEventListener('mouseleave', this.boundOnProgressLeave as EventListener);
        }

        // 銷毀渲染器
        if (this.renderer) {
            this.renderer.destroy();
            this.renderer = null;
        }

        // 移除 DOM
        this.thumbnailWrapper?.remove();
    }
}

export default ThumbnailPlugin;
